class Solution {
public int maxSumBST(TreeNode root) {List<TreeNode> order=new ArrayList<>();order.add(root);for(int i=0;i<order.size();i++) {TreeNode n=order.get(i);if(n.left!=null) order.add(n.left);if(n.right!=null) order.add(n.right);}Map<TreeNode,long[]> info=new IdentityHashMap<>();info.put(null,new long[]{1,Long.MAX_VALUE,Long.MIN_VALUE,0});int best=0;for(int i=order.size()-1;i>=0;i--) {TreeNode n=order.get(i);long[] l=info.get(n.left),r=info.get(n.right);boolean valid=l[0]==1&&r[0]==1&&l[2]<n.val&&n.val<r[1];long sum=l[3]+r[3]+n.val;info.put(n,new long[]{valid?1:0,Math.min(n.val,l[1]),Math.max(n.val,r[2]),sum});if(valid) best=Math.max(best,(int)sum);}return best;}
}
